#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <cmath>
#include <numeric>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string s;
    std::cin >> s;

    std::vector<int> a(6);
    for (int i = 0; i < 6; ++i) {
        a[i] = s[i] - '0';
    }

    int sum1 = a[0] + a[1] + a[2];
    int sum2 = a[3] + a[4] + a[5];

    if (sum1 == sum2) {
        std::cout << 0 << '\n';
        return 0;
    }

    std::vector<int> a1 = {a[0], a[1], a[2]};
    std::vector<int> a2 = {a[3], a[4], a[5]};
    std::sort(a1.begin(), a1.end());
    std::sort(a2.begin(), a2.end());

    std::vector<int> changes(6);
    if (sum1 > sum2) {
        for (int k = 0; k < 3; ++k) {
            changes[k] = a1[k];
            changes[k + 3] = 9 - a2[k];
        }
    } else {
        for (int k = 0; k < 3; ++k) {
            changes[k] = a2[k];
            changes[k + 3] = 9 - a1[k];
        }
    }

    std::sort(changes.begin(), changes.end());

    int dif = std::abs(sum1 - sum2);
    int sumdif = 0;
    int answer = 0;
    int i = 5;
    while (sumdif < dif) {
        sumdif += changes[i];
        --i;
        ++answer;
    }

    std::cout << answer << '\n';
    return 0;
}

