    vector<int> a(6);
    for (int i = 0; i < 6; ++i) {
        a[i] = s[i] - '0';
    }

    int sum1 = a[0] + a[1] + a[2];
    int sum2 = a[3] + a[4] + a[5];

    if (sum1 == sum2) {
        cout << 0 << "\n";
        return 0;
    }

    vector<int> a1 = {a[0], a[1], a[2]};
    vector<int> a2 = {a[3], a[4], a[5]};

    sort(a1.begin(), a1.end());
    sort(a2.begin(), a2.end());

    vector<int> changes(6);

    if (sum1 > sum2) {
        for (int k = 0; k < 3; ++k) {
            changes[k] = a1[k];
            changes[k + 3] = 9 - a2[k];
        }
    } else {
        for (int k = 0; k < 3; ++k) {
            changes[k] = a2[k];
            changes[k + 3] = 9 - a1[k];
        }
    }

    sort(changes.begin(), changes.end());

    int dif = abs(sum1 - sum2);
